class Person {
  private final String name;
  private final int age;
  Person(String name, int age) {
    this.name = name;
    this.age = age;
  }
}
enum Colour {
  RED("r");
  Colour(String code) {
    this.code = code;
  }
  private final String code;
}

import java.util.Objects;
class Failure extends RuntimeException {
  private final String code;
  private final String name;
  Failure(String code) {
    super(code);
    this.code = code;
    this.name = "";
  }
  Failure() {
    this("none");
  }
  Failure(String code, String name) {
    this.code = Objects.requireNonNull(code);
    this.name = name.trim();
  }
  private Failure(int unused) {
  }
}
class Node {
  private final Node next;
  Node(Node next) {
    this.next = next.next;
  }
}
class Range {
  private final int lower;
  private final int upper;
  Range(int value) {
    this.lower = value;
    this.upper = value;
  }
  Range(int from, int to) {
    this.lower = to;
    this.upper = from;
  }
  Range(int lower, int upper, boolean unused) {
    this.lower = lower;
    this.upper = upper;
  }
}
